-- supabase/sql/exam_question_bank_viteee_set1.sql
--
-- First curated question-bank batch for 'VITEEE' (see exam_patterns_viteee.sql for the exam's
-- structure). Same exam_question_bank table/schema as the other sets -- no migration needed.
--
-- Like MHT-CET/NEET/BITSAT (and unlike the JEE sets), VITEEE's real format is 100%
-- single-best-response MCQ (4 options, exactly one correct) -- no multi-correct, numerical, or
-- descriptive format in the actual exam. 16 chapters (4 Physics, 4 Chemistry, 4 Mathematics, 2
-- English, 2 Aptitude) each get 4 questions -- the English and Aptitude sections mirror BITSAT's
-- English Proficiency/Logical Reasoning sections but with fresh, distinct content here.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_viteee.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Physics: Mechanics
('VITEEE', 'Physics', 'Mechanics', 'easy', 'mcq',
 'The SI unit of pressure is the:',
 '[{"text":"Newton","isCorrect":false},{"text":"Pascal","isCorrect":true},{"text":"Joule","isCorrect":false},{"text":"Watt","isCorrect":false}]'::jsonb,
 null, 'Pressure, defined as force per unit area, is measured in pascals (Pa), where 1 Pa = 1 N/m^2.'),
('VITEEE', 'Physics', 'Mechanics', 'easy', 'mcq',
 'A body dropped from a height, in the absence of air resistance, falls under:',
 '[{"text":"Uniform velocity","isCorrect":false},{"text":"Uniform acceleration","isCorrect":true},{"text":"Decreasing acceleration","isCorrect":false},{"text":"Zero acceleration","isCorrect":false}]'::jsonb,
 null, 'In free fall (ignoring air resistance), a body experiences a constant acceleration g due to gravity, so it undergoes uniformly accelerated motion.'),
('VITEEE', 'Physics', 'Mechanics', 'medium', 'mcq',
 'The work-energy theorem states that the net work done on a body equals its:',
 '[{"text":"Change in potential energy","isCorrect":false},{"text":"Change in kinetic energy","isCorrect":true},{"text":"Total mechanical energy","isCorrect":false},{"text":"Change in momentum","isCorrect":false}]'::jsonb,
 null, 'The work-energy theorem states that the net work done on an object by all forces equals the change in its kinetic energy.'),
('VITEEE', 'Physics', 'Mechanics', 'medium', 'mcq',
 'The dimensional formula of momentum is:',
 '[{"text":"[MLT^-1]","isCorrect":true},{"text":"[MLT^-2]","isCorrect":false},{"text":"[ML^2T^-2]","isCorrect":false},{"text":"[ML^2T^-1]","isCorrect":false}]'::jsonb,
 null, 'Momentum = mass x velocity, giving dimensions [M][LT^-1] = [MLT^-1].'),

-- Physics: Electrodynamics
('VITEEE', 'Physics', 'Electrodynamics', 'easy', 'mcq',
 'Ohm''s law relates voltage V, current I, and resistance R as:',
 '[{"text":"V = IR","isCorrect":true},{"text":"V = I/R","isCorrect":false},{"text":"V = I + R","isCorrect":false},{"text":"I = VR","isCorrect":false}]'::jsonb,
 null, 'Ohm''s law states that the voltage across a conductor is directly proportional to the current through it, with resistance as the constant of proportionality: V = IR.'),
('VITEEE', 'Physics', 'Electrodynamics', 'medium', 'mcq',
 'The magnitude of the magnetic force on a charge q moving with velocity v at angle theta to a magnetic field B is given by:',
 '[{"text":"qvB*sin(theta)","isCorrect":true},{"text":"qvB*cos(theta)","isCorrect":false},{"text":"qvB","isCorrect":false},{"text":"qv/B","isCorrect":false}]'::jsonb,
 null, 'The magnitude of the Lorentz magnetic force is F = qvB*sin(theta), where theta is the angle between the velocity and magnetic field vectors.'),
('VITEEE', 'Physics', 'Electrodynamics', 'medium', 'mcq',
 'In a series LCR circuit at resonance, the impedance of the circuit is:',
 '[{"text":"Maximum, equal to (XL+XC)","isCorrect":false},{"text":"Minimum, equal to the resistance R","isCorrect":true},{"text":"Zero","isCorrect":false},{"text":"Infinite","isCorrect":false}]'::jsonb,
 null, 'At resonance, the inductive and capacitive reactances cancel (XL=XC), leaving only the resistance R, so the impedance is at its minimum possible value.'),
('VITEEE', 'Physics', 'Electrodynamics', 'easy', 'mcq',
 'The SI unit of magnetic flux density (magnetic field strength) is the:',
 '[{"text":"Weber","isCorrect":false},{"text":"Tesla","isCorrect":true},{"text":"Henry","isCorrect":false},{"text":"Farad","isCorrect":false}]'::jsonb,
 null, 'Magnetic flux density (B) is measured in tesla (T), while magnetic flux itself is measured in weber (Wb).'),

-- Physics: Optics and Wave Optics
('VITEEE', 'Physics', 'Optics and Wave Optics', 'medium', 'mcq',
 'In Young''s double slit experiment, constructive interference occurs when the path difference between the two waves is:',
 '[{"text":"An integral multiple of the wavelength","isCorrect":true},{"text":"An odd multiple of half the wavelength","isCorrect":false},{"text":"Always zero","isCorrect":false},{"text":"Equal to the slit separation","isCorrect":false}]'::jsonb,
 null, 'Constructive interference (bright fringes) occurs when the path difference equals n*lambda, an integral multiple of the wavelength, so the waves arrive in phase.'),
('VITEEE', 'Physics', 'Optics and Wave Optics', 'easy', 'mcq',
 'A converging (convex) lens used as a simple magnifying glass forms an image that is:',
 '[{"text":"Real, inverted, and magnified","isCorrect":false},{"text":"Virtual, erect, and magnified","isCorrect":true},{"text":"Real, erect, and diminished","isCorrect":false},{"text":"Virtual, inverted, and diminished","isCorrect":false}]'::jsonb,
 null, 'When the object is placed within the focal length of a convex lens, it produces a virtual, erect, magnified image -- the basis of a simple magnifying glass.'),
('VITEEE', 'Physics', 'Optics and Wave Optics', 'medium', 'mcq',
 'Polarization is a phenomenon that can be exhibited only by:',
 '[{"text":"Longitudinal waves","isCorrect":false},{"text":"Transverse waves","isCorrect":true},{"text":"Sound waves in air","isCorrect":false},{"text":"All types of waves equally","isCorrect":false}]'::jsonb,
 null, 'Polarization restricts the vibration of a wave to a single plane, which is possible only for transverse waves (like light), not longitudinal waves (like sound in air).'),
('VITEEE', 'Physics', 'Optics and Wave Optics', 'easy', 'mcq',
 'The power of a lens is measured in units of:',
 '[{"text":"Diopter","isCorrect":true},{"text":"Candela","isCorrect":false},{"text":"Lux","isCorrect":false},{"text":"Lumen","isCorrect":false}]'::jsonb,
 null, 'Lens power, defined as the reciprocal of focal length in meters, is measured in diopters (D).'),

-- Physics: Modern Physics and Semiconductor Devices
('VITEEE', 'Physics', 'Modern Physics and Semiconductor Devices', 'medium', 'mcq',
 'The stopping potential in the photoelectric effect depends on:',
 '[{"text":"The intensity of incident light only","isCorrect":false},{"text":"The frequency of incident light","isCorrect":true},{"text":"The area of the metal surface","isCorrect":false},{"text":"The distance of the light source","isCorrect":false}]'::jsonb,
 null, 'Stopping potential is determined by the maximum kinetic energy of photoelectrons, which depends on the frequency of incident light, not its intensity.'),
('VITEEE', 'Physics', 'Modern Physics and Semiconductor Devices', 'medium', 'mcq',
 'A p-n junction diode conducts significantly when forward biased mainly because:',
 '[{"text":"The depletion region widens","isCorrect":false},{"text":"The depletion region narrows, lowering the potential barrier","isCorrect":true},{"text":"The diode''s temperature drops","isCorrect":false},{"text":"Majority carriers are repelled from the junction","isCorrect":false}]'::jsonb,
 null, 'Forward biasing reduces the width of the depletion region and lowers the potential barrier, allowing majority carriers to flow easily across the junction.'),
('VITEEE', 'Physics', 'Modern Physics and Semiconductor Devices', 'medium', 'mcq',
 'The mass defect observed in a nucleus, compared to the sum of masses of its individual nucleons, is converted into the nucleus''s:',
 '[{"text":"Kinetic energy","isCorrect":false},{"text":"Binding energy","isCorrect":true},{"text":"Electric charge","isCorrect":false},{"text":"Magnetic moment","isCorrect":false}]'::jsonb,
 null, 'The mass defect, via E=mc^2, corresponds to the binding energy that holds the nucleons together in the nucleus.'),
('VITEEE', 'Physics', 'Modern Physics and Semiconductor Devices', 'easy', 'mcq',
 'In a common-emitter transistor configuration, the current gain is denoted by:',
 '[{"text":"Alpha","isCorrect":false},{"text":"Beta","isCorrect":true},{"text":"Gamma","isCorrect":false},{"text":"Delta","isCorrect":false}]'::jsonb,
 null, 'In common-emitter configuration, current gain (ratio of collector current to base current) is denoted by beta (also written hFE).'),

-- Chemistry: Physical Chemistry
('VITEEE', 'Chemistry', 'Physical Chemistry', 'medium', 'mcq',
 'According to the first law of thermodynamics, the change in internal energy deltaU of a system is given by:',
 '[{"text":"deltaU = q + w","isCorrect":true},{"text":"deltaU = q * w","isCorrect":false},{"text":"deltaU = q/w","isCorrect":false},{"text":"deltaU = w - q","isCorrect":false}]'::jsonb,
 null, 'The first law of thermodynamics (IUPAC convention) states deltaU = q + w, where q is heat absorbed by the system and w is work done on the system.'),
('VITEEE', 'Chemistry', 'Physical Chemistry', 'medium', 'mcq',
 'The half-life of a first-order reaction is:',
 '[{"text":"Directly proportional to initial concentration","isCorrect":false},{"text":"Independent of initial concentration","isCorrect":true},{"text":"Inversely proportional to initial concentration","isCorrect":false},{"text":"Proportional to the square of initial concentration","isCorrect":false}]'::jsonb,
 null, 'For a first-order reaction, t(1/2) = 0.693/k, which does not depend on the initial concentration of the reactant.'),
('VITEEE', 'Chemistry', 'Physical Chemistry', 'medium', 'mcq',
 'An ideal solution is best described as one that:',
 '[{"text":"Obeys Raoult''s law at all concentrations","isCorrect":true},{"text":"Shows large positive deviation from Raoult''s law","isCorrect":false},{"text":"Cannot be formed from two liquids","isCorrect":false},{"text":"Has zero vapor pressure","isCorrect":false}]'::jsonb,
 null, 'An ideal solution obeys Raoult''s law across the entire concentration range, with zero enthalpy and volume change on mixing.'),
('VITEEE', 'Chemistry', 'Physical Chemistry', 'hard', 'mcq',
 'The unit of the equilibrium constant Kp for a gaseous reaction depends on:',
 '[{"text":"The temperature of the reaction only","isCorrect":false},{"text":"The change in the number of moles of gas (delta n) in the reaction","isCorrect":true},{"text":"The total pressure of the system","isCorrect":false},{"text":"The catalyst used","isCorrect":false}]'::jsonb,
 null, 'Kp = Kc(RT)^(delta n), so its units depend on delta n, the difference between moles of gaseous products and reactants; if delta n = 0, Kp is dimensionless.'),

