-- English: Grammar and Sentence Correction
('VITEEE', 'English', 'Grammar and Sentence Correction', 'medium', 'mcq',
 'Which sentence is grammatically correct?',
 '[{"text":"Each of the students have submitted their assignment.","isCorrect":false},{"text":"Each of the students has submitted his or her assignment.","isCorrect":true},{"text":"Each of the students has submitted their assignments.","isCorrect":false},{"text":"Each of the students have submitted his assignment.","isCorrect":false}]'::jsonb,
 null, '"Each" is a singular subject, requiring the singular verb "has" and singular possessive "his or her", not the plural "have"/"their".'),
('VITEEE', 'English', 'Grammar and Sentence Correction', 'hard', 'mcq',
 'Choose the correct word to complete: "He is one of the best players who ___ ever played this game."',
 '[{"text":"has","isCorrect":false},{"text":"have","isCorrect":true},{"text":"having","isCorrect":false},{"text":"had","isCorrect":false}]'::jsonb,
 null, '"Who" here refers back to "players" (plural), from "one of the best players who...", so the verb must agree in the plural: "have ever played".'),
('VITEEE', 'English', 'Grammar and Sentence Correction', 'medium', 'mcq',
 'Choose the correct article to complete: "___ European Union has 27 member countries."',
 '[{"text":"A","isCorrect":false},{"text":"An","isCorrect":false},{"text":"The","isCorrect":true},{"text":"No article is needed","isCorrect":false}]'::jsonb,
 null, '"European Union" is a specific, unique organization, requiring the definite article "The" (and note "European" begins with a consonant sound, ruling out "An").'),
('VITEEE', 'English', 'Grammar and Sentence Correction', 'medium', 'mcq',
 'Which sentence uses the semicolon correctly?',
 '[{"text":"I have a big exam tomorrow; I can''t go out tonight.","isCorrect":true},{"text":"I have a big exam tomorrow; because I can''t go out tonight.","isCorrect":false},{"text":"I have a big exam tomorrow, I can''t go out tonight;","isCorrect":false},{"text":"I have a big; exam tomorrow I can''t go out tonight.","isCorrect":false}]'::jsonb,
 null, 'A semicolon correctly joins two closely related independent clauses without a conjunction, as in "I have a big exam tomorrow; I can''t go out tonight."'),

